from PIL import Image
import numpy as np
a=np.array(Image.open('input/drawing.jpg').convert('L'))
d=a<100
for x in [103,179,224,284,329,330,396]:
    ys=np.where(d[:,x])[0]
    # group
    groups=[]
    for y in ys:
        if groups and y-groups[-1][-1]<=1: groups[-1].append(y)
        else: groups.append([y])
    print('x',x,[(g[0],g[-1]) for g in groups if len(g)>2])
# horizontal lines
for y in [67,68,142,143,172,173]:
    xs=np.where(d[y,:])[0]
    groups=[]
    for x in xs:
        if groups and x-groups[-1][-1]<=1: groups[-1].append(x)
        else: groups.append([x])
    print('y',y,[(g[0],g[-1]) for g in groups if len(g)>5])
