    if long:
        print('y',y,long)
print('--- vertical')
for x in range(90,340):
    ys=np.where(d[200:560,x])[0]+200
    groups=[]
    for y in ys:
        if groups and y-groups[-1][-1]<=1: groups[-1].append(y)
        else: groups.append([y])
    long=[(g[0],g[-1]) for g in groups if len(g)>15]
    if long:
        print('x',x,long)
